1	// services/openrouter.ts - OpenRouter API calls (classifier + completions)
2	//
3	// Este módulo concentra a comunicação com o OpenRouter E o harness que torna
4	// Darcy robusto a giro de modelos grátis: normalizeAnswer() uniformiza a saída
5	// e isAcceptableAnswer() barra respostas ruins (recusa, vazio, vazamento de
6	// prompt) para que a cascata de fallback troque de modelo.
7	
8	import { LLM } from "../config.ts";
9	
10	async function fetchWithTimeout(url: string, init: RequestInit, timeoutMs: number): Promise<Response> {
11	    const ctrl = new AbortController();
12	    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
13	    try {
14	        return await fetch(url, { ...init, signal: ctrl.signal });
15	    } finally {
16	        clearTimeout(timer);
17	    }
18	}
19	
20	// Higiene de log (LGPD): o corpo de erro do OpenRouter pode ecoar o prompt
21	// (com PII de aluno) ou tokens em URLs. Trunca para ~200 chars e redige
22	// segredos em URLs antes de cair no log. Nunca assumir que o corpo e seguro.
23	function safeErrorSnippet(text: string | null | undefined): string {
24	    if (!text) return "";
25	    const redacted = String(text).replace(/(sesskey|wstoken|token|api[_-]?key)=[^&\s"']+/gi, "$1=[REDACTED]");
26	    return redacted.length > 200 ? redacted.substring(0, 200) + "…" : redacted;
27	}
28	
29	// ── Normalização de saída (uniformiza artefatos entre modelos) ───────────────
30	// Modelos diferentes vazam coisas diferentes: blocos de raciocínio (<think>),
31	// rótulos de papel ("Assistant:", "Darcy:"), ou embrulham a resposta inteira
32	// numa cerca de código. Esta função deixa a saída uniforme, venha de qual
33	// modelo vier. É idempotente e segura para conteúdo legítimo.
34	const REASONING_TAGS = "think|thinking|thought|reasoning|reflect|inner_monologue";
35	
36	export function normalizeAnswer(text: string | null | undefined): string {
37	    if (!text) return "";
38	    let t = text;
39	    // 1. Remove blocos de raciocínio FECHADOS (<think>...</think> etc.)
40	    t = t.replace(new RegExp(`<(${REASONING_TAGS})>[\\s\\S]*?<\\/\\1>`, "gi"), "");
41	    // 2. Remove bloco de raciocínio ABERTO e não fechado (truncado por max_tokens):
42	    //    se sobrou um <think> sem fechamento, descarta dele até o fim — senão o
43	    //    raciocínio do modelo vazaria para o aluno.
44	    t = t.replace(new RegExp(`<(${REASONING_TAGS})>[\\s\\S]*$`, "i"), "");
45	    // 3. Remove tags órfãs de papel/estrutura que alguns modelos ecoam
46	    t = t.replace(/<\/?(system|user|assistant|instruction|prompt)>/gi, "");
47	    // 4. Remove rótulo de papel no INÍCIO ("Assistant:", "Darcy:", "AI:", "Bot:")
48	    t = t.replace(/^\s*(?:assistant|darcy|ai|bot)\s*:\s*/i, "");
49	    // 4b. Preâmbulo de raciocínio VAZADO: alguns modelos free (ex.: nemotron) às
50	    //     vezes despejam o chain-of-thought EM INGLÊS antes da resposta. Como o
51	    //     Darcy responde em português, uma abertura em inglês com marcador de
52	    //     raciocínio é inequivocamente vazamento — cortamos até a resposta real.
53	    if (/^\s*(?:okay|alright|hmm|so,|sure,|let me|let's|first,?\s+i|the user|i need to|i should|i'?ll|i will|we need|we should|i'?m going to|the question|to answer|based on the)/i.test(t)) {
54	        const ans = t.match(/(?:^|\n)\s*(?:\d+[.)]\s|[-*•]\s|#{1,6}\s|\*\*)/);
55	        if (ans && ans.index && ans.index > 0) {
56	            t = t.slice(ans.index);                                   // corta até o 1º item de lista/negrito/título
57	        } else {
58	            t = t.replace(/^[\s\S]*?(?:\n\n+|(?<=[.!?])\s+(?=[A-ZÀ-Ú]))/, ""); // ou até a 1ª quebra/frase
59	        }
60	    }
61	    // 5. Se a resposta INTEIRA está embrulhada numa única cerca de código, desembrulha
62	    const fence = t.trim().match(/^```[a-zA-Z]*\n([\s\S]*?)\n?```$/);
63	    if (fence) t = fence[1];
64	    return t.trim();
65	}
66	
67	// ── Gate de qualidade (decide se a resposta serve ou se troca de modelo) ─────
68	// Retorna false para saídas que NÃO queremos servir ao aluno. Em caso de
69	// reprovação, o chamador tenta o próximo modelo da cascata. É conservador de
70	// propósito: só barra padrões claramente ruins, para não rejeitar resposta boa.
71	export function isAcceptableAnswer(text: string | null | undefined): boolean {
72	    const t = (text || "").trim();
73	    if (t.length < 2) return false;
74	    // Recusas típicas (inglês) — queremos uma resposta útil, não uma desistência.
75	    if (/\b(i\s+(can'?t|cannot|am\s+unable\s+to)\s+(help|assist|do)|as\s+an\s+ai\s+(language\s+)?model|i'?m\s+just\s+an\s+ai)\b/i.test(t)) return false;
76	    // Recusa explícita em português.
77	    if (/n[ãa]o\s+posso\s+(te\s+)?ajudar\s+com\s+(isso|essa|esse)/i.test(t)) return false;
78	    // Vazamento do system prompt / estrutura interna.
79	    if (/REGRA CR[IÍ]TICA DE SEGURAN[ÇC]A|<knowledge_base|<identity>|<active_platform>/i.test(t)) return false;
80	    // Vazamento de raciocínio em inglês NÃO removido pela normalização → rejeita
81	    // para a cascata tentar outro modelo (rede dupla com normalizeAnswer 4b).
82	    if (/^\s*(?:okay|alright|let me|first,?\s+i|the user|i need to|i should|i'?ll|we need|i'?m going to|to answer|based on the)\b/i.test(t)) return false;
83	    return true;
84	}
85	
86	// ── Revisor de texto (2ª camada, GATED) ──────────────────────────────────────
87	// Chamado SÓ quando o reparo determinístico (../_shared/text-repair.ts) ainda
88	// detecta resíduo suspeito. É best-effort: qualquer falha/recusa/divergência de
89	// tamanho devolve null e o chamador MANTÉM o texto já reparado (nunca piora).
90	// Usa o modelo com melhor PT-BR da casa (llama-3.3-70b) em temperatura 0 — tarefa
91	// de REVISÃO é muito mais simples que geração, então o risco de o revisor "comer"
92	// espaço é baixo (e, se acontecer, o chamador roda o determinístico de novo por cima).
93	const PROOFREAD_MODEL = "meta-llama/llama-3.3-70b-instruct:free";
94	const PROOFREAD_SYSTEM = `Você é um REVISOR de texto em português do Brasil. Sua ÚNICA tarefa é corrigir erros de digitação, ESPAÇAMENTO, ortografia e acentuação, mantendo EXATAMENTE:
95	- o sentido e as informações (NÃO adicione, NÃO remova, NÃO resuma, NÃO responda nada, NÃO comente);
96	- o idioma (português) e o tom;
97	- toda a formatação Markdown, listas, links, quebras de linha e blocos de código (NÃO altere o que está entre crases).
98	Corrija ESPECIALMENTE palavras grudadas (ex.: "conteúdoacadêmico" -> "conteúdo acadêmico"; "otema" -> "o tema") e espaços faltando após pontuação.
99	Responda SOMENTE com o texto corrigido — sem aspas, sem prefixos, sem explicações.`;
100	
101	export async function proofreadAnswer(apiKey: string, text: string): Promise<string | null> {
102	    const input = (text || "").trim();
103	    if (input.length < 8) return null; // curto demais p/ valer uma chamada
104	    try {
105	        const response = await fetchWithTimeout('https://openrouter.ai/api/v1/chat/completions', {
106	            method: 'POST',
107	            headers: {
108	                'Authorization': "Bearer " + apiKey,
109	                'Content-Type': 'application/json',
110	                'HTTP-Referer': LLM.REFERER,
111	                'X-Title': LLM.TITLE
112	            },
113	            body: JSON.stringify({
114	                model: PROOFREAD_MODEL,
115	                messages: [
116	                    { role: "system", content: PROOFREAD_SYSTEM },
117	                    { role: "user", content: input }
118	                ],
119	                temperature: 0,
120	                max_tokens: Math.min(1200, Math.ceil(input.length / 2) + 200)
121	            })
122	        }, LLM.CLASSIFIER_TIMEOUT_MS);
123	
124	        if (!response.ok) return null;
125	        const data = await response.json();
126	        const out = normalizeAnswer(data.choices?.[0]?.message?.content);
127	        if (!out) return null;
128	        // Sanidade: revisão NÃO deve mudar drasticamente o tamanho (sinal de que
129	        // resumiu/respondeu em vez de revisar) nem vazar inglês/recusa.
130	        if (out.length < input.length * 0.6 || out.length > input.length * 1.8) return null;
131	        if (!isAcceptableAnswer(out)) return null;
132	        return out;
133	    } catch (_e) {
134	        return null; // best-effort: chamador mantém o texto determinístico
135	    }
136	}
137	
138	export type PedagogicalIntent = "ANALOGY_MODE" | "CHALLENGE_MODE" | "DEFAULT_MODE";
139	
140	export interface PedagogicalMode {
141	    intent: PedagogicalIntent;
142	    reasoning: string;
143	}
144	
145	export async function classifyPedagogicalIntent(
146	    apiKey: string,
147	    lastMessage: string,
148	    _history: any[]
149	): Promise<PedagogicalMode> {
150	    if (!lastMessage || lastMessage.trim().length === 0) {
151	        return { intent: "DEFAULT_MODE", reasoning: "Mensagem vazia." };
152	    }
153	
154	    const classificationPrompt = `
155	Analyze the student's last message and classify their pedagogical need.
156	
157	Categories:
158	1. CONFUSION_HIGH (Student is lost, says "I don't understand", "Confused", "Hard") -> ANALOGY_MODE
159	2. MASTERY_HIGH (Student says "Easy", "I know this", "Give me harder stuff") -> CHALLENGE_MODE
160	3. NEUTRAL (Standard question) -> DEFAULT_MODE
161	
162	OUTPUT FORMAT (JSON ONLY):
163	{
164	  "intent": "ANALOGY_MODE" | "CHALLENGE_MODE" | "DEFAULT_MODE",
165	  "reasoning": "Brief explanation of why (max 1 sentence)"
166	}
167	`;
168	
169	    try {
170	        const response = await fetchWithTimeout('https://openrouter.ai/api/v1/chat/completions', {
171	            method: 'POST',
172	            headers: {
173	                'Authorization': "Bearer " + apiKey,
174	                'Content-Type': 'application/json',
175	                'HTTP-Referer': LLM.REFERER,
176	                'X-Title': LLM.TITLE
177	            },
178	            body: JSON.stringify({
179	                model: LLM.CLASSIFIER_MODEL,
180	                messages: [
181	                    { role: "system", content: classificationPrompt },
182	                    { role: "user", content: lastMessage }
183	                ],
184	                temperature: LLM.TEMPERATURE_CLASSIFIER,
185	                max_tokens: LLM.MAX_TOKENS_CLASSIFIER,
186	                response_format: { type: "json_object" }
187	            })
188	        }, LLM.CLASSIFIER_TIMEOUT_MS);
189	
190	        if (!response.ok) {
191	            return { intent: "DEFAULT_MODE", reasoning: "Erro na analise (API): " + response.status };
192	        }
193	
194	        const data = await response.json();
195	        const content: string = data.choices?.[0]?.message?.content?.trim() || "";
196	        const VALID: PedagogicalIntent[] = ["ANALOGY_MODE", "CHALLENGE_MODE", "DEFAULT_MODE"];
197	
198	        try {
199	            const parsed = JSON.parse(content);
200	            const intent: PedagogicalIntent = VALID.includes(parsed?.intent) ? parsed.intent : "DEFAULT_MODE";
201	            return {
202	                intent,
203	                reasoning: parsed?.reasoning || "Analise realizada, mas sem justificativa."
204	            };
205	        } catch (_e) {
206	            // Modelo não devolveu JSON válido — extrai a intenção por palavra-chave.
207	            if (content.includes("ANALOGY_MODE")) return { intent: "ANALOGY_MODE", reasoning: content.slice(0, 200) };
208	            if (content.includes("CHALLENGE_MODE")) return { intent: "CHALLENGE_MODE", reasoning: content.slice(0, 200) };
209	            return { intent: "DEFAULT_MODE", reasoning: content.slice(0, 200) };
210	        }
211	
212	    } catch (_e) {
213	        return { intent: "DEFAULT_MODE", reasoning: "Falha interna no classificador." };
214	    }
215	}
216	
217	// usage: tokens reais + custo (OpenRouter devolve usage.cost com usage.include).
218	export interface OpenRouterUsage {
219	    prompt_tokens?: number;
220	    completion_tokens?: number;
221	    total_tokens?: number;
222	    cost?: number;
223	}
224	
225	export async function callOpenRouterWithTools(
226	    apiKey: string,
227	    messages: any[],
228	    tools: any[],
229	    model: string,
230	    toolChoice: "auto" | "required" = "auto"
231	): Promise<{ content?: string; tool_calls?: any[]; error?: string; usage?: OpenRouterUsage | null; finish_reason?: string | null }> {
232	    console.log("[OPENROUTER] Chamando " + model + " com " + tools.length + " tools");
233	
234	    let response: Response;
235	    try {
236	        response = await fetchWithTimeout('https://openrouter.ai/api/v1/chat/completions', {
237	            method: 'POST',
238	            headers: {
239	                'Authorization': "Bearer " + apiKey,
240	                'Content-Type': 'application/json',
241	                'HTTP-Referer': LLM.REFERER,
242	                'X-Title': LLM.TITLE
243	            },
244	            body: JSON.stringify({
245	                model: model,
246	                messages: messages,
247	                ...(tools.length > 0 ? { tools, tool_choice: toolChoice } : {}),
248	                temperature: LLM.TEMPERATURE,
249	                max_tokens: LLM.MAX_TOKENS,
250	                usage: { include: true }   // pede tokens + custo no corpo da resposta
251	            })
252	        }, LLM.TIMEOUT_MS);
253	    } catch (e: any) {
254	        const reason = e?.name === 'AbortError' ? 'timeout' : (e?.message || 'network');
255	        console.error("[OPENROUTER] Falha de rede em " + model + ": " + reason);
256	        return { error: "Modelo " + model + " indisponivel: " + reason };
257	    }
258	
259	    if (!response.ok) {
260	        const errorText = await response.text();
261	        console.error("[OPENROUTER] Erro " + response.status + ": " + safeErrorSnippet(errorText));
262	        return { error: "Modelo " + model + " falhou: " + response.status };
263	    }
264	
265	    const data = await response.json();
266	    const choice = data.choices?.[0]?.message;
267	
268	    if (!choice) {
269	        return { error: "Resposta invalida do modelo" };
270	    }
271	
272	    return {
273	        content: choice.content,
274	        tool_calls: choice.tool_calls,
275	        usage: data.usage ?? null,
276	        finish_reason: data.choices?.[0]?.finish_reason ?? null,
277	    };
278	}
