// services/openrouter.ts - OpenRouter API calls (classifier + completions)
//
// Este módulo concentra a comunicação com o OpenRouter E o harness que torna
// Darcy robusto a giro de modelos grátis: normalizeAnswer() uniformiza a saída
// e isAcceptableAnswer() barra respostas ruins (recusa, vazio, vazamento de
// prompt) para que a cascata de fallback troque de modelo.

import { LLM } from "../config.ts";

async function fetchWithTimeout(url: string, init: RequestInit, timeoutMs: number): Promise<Response> {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
        return await fetch(url, { ...init, signal: ctrl.signal });
    } finally {
        clearTimeout(timer);
    }
}

// Higiene de log (LGPD): o corpo de erro do OpenRouter pode ecoar o prompt
// (com PII de aluno) ou tokens em URLs. Trunca para ~200 chars e redige
// segredos em URLs antes de cair no log. Nunca assumir que o corpo e seguro.
function safeErrorSnippet(text: string | null | undefined): string {
    if (!text) return "";
    const redacted = String(text).replace(/(sesskey|wstoken|token|api[_-]?key)=[^&\s"']+/gi, "$1=[REDACTED]");
    return redacted.length > 200 ? redacted.substring(0, 200) + "…" : redacted;
}

// ── Normalização de saída (uniformiza artefatos entre modelos) ───────────────
// Modelos diferentes vazam coisas diferentes: blocos de raciocínio (<think>),
// rótulos de papel ("Assistant:", "Darcy:"), ou embrulham a resposta inteira
// numa cerca de código. Esta função deixa a saída uniforme, venha de qual
// modelo vier. É idempotente e segura para conteúdo legítimo.
const REASONING_TAGS = "think|thinking|thought|reasoning|reflect|inner_monologue";

export function normalizeAnswer(text: string | null | undefined): string {
    if (!text) return "";
    let t = text;
    // 1. Remove blocos de raciocínio FECHADOS (<think>...</think> etc.)
    t = t.replace(new RegExp(`<(${REASONING_TAGS})>[\\s\\S]*?<\\/\\1>`, "gi"), "");
    // 2. Remove bloco de raciocínio ABERTO e não fechado (truncado por max_tokens):
    //    se sobrou um <think> sem fechamento, descarta dele até o fim — senão o
    //    raciocínio do modelo vazaria para o aluno.
    t = t.replace(new RegExp(`<(${REASONING_TAGS})>[\\s\\S]*$`, "i"), "");
    // 3. Remove tags órfãs de papel/estrutura que alguns modelos ecoam
    t = t.replace(/<\/?(system|user|assistant|instruction|prompt)>/gi, "");
    // 4. Remove rótulo de papel no INÍCIO ("Assistant:", "Darcy:", "AI:", "Bot:")
    t = t.replace(/^\s*(?:assistant|darcy|ai|bot)\s*:\s*/i, "");
    // 4b. Preâmbulo de raciocínio VAZADO: alguns modelos free (ex.: nemotron) às
    //     vezes despejam o chain-of-thought EM INGLÊS antes da resposta. Como o
    //     Darcy responde em português, uma abertura em inglês com marcador de
    //     raciocínio é inequivocamente vazamento — cortamos até a resposta real.
    if (/^\s*(?:okay|alright|hmm|so,|sure,|let me|let's|first,?\s+i|the user|i need to|i should|i'?ll|i will|we need|we should|i'?m going to|the question|to answer|based on the)/i.test(t)) {
        const ans = t.match(/(?:^|\n)\s*(?:\d+[.)]\s|[-*•]\s|#{1,6}\s|\*\*)/);
        if (ans && ans.index && ans.index > 0) {
            t = t.slice(ans.index);                                   // corta até o 1º item de lista/negrito/título
        } else {
            t = t.replace(/^[\s\S]*?(?:\n\n+|(?<=[.!?])\s+(?=[A-ZÀ-Ú]))/, ""); // ou até a 1ª quebra/frase
        }
    }
    // 5. Se a resposta INTEIRA está embrulhada numa única cerca de código, desembrulha
    const fence = t.trim().match(/^```[a-zA-Z]*\n([\s\S]*?)\n?```$/);
    if (fence) t = fence[1];
    return t.trim();
}

// ── Gate de qualidade (decide se a resposta serve ou se troca de modelo) ─────
// Retorna false para saídas que NÃO queremos servir ao aluno. Em caso de
// reprovação, o chamador tenta o próximo modelo da cascata. É conservador de
// propósito: só barra padrões claramente ruins, para não rejeitar resposta boa.
export function isAcceptableAnswer(text: string | null | undefined): boolean {
    const t = (text || "").trim();
    if (t.length < 2) return false;
    // Recusas típicas (inglês) — queremos uma resposta útil, não uma desistência.
    if (/\b(i\s+(can'?t|cannot|am\s+unable\s+to)\s+(help|assist|do)|as\s+an\s+ai\s+(language\s+)?model|i'?m\s+just\s+an\s+ai)\b/i.test(t)) return false;
    // Recusa explícita em português.
    if (/n[ãa]o\s+posso\s+(te\s+)?ajudar\s+com\s+(isso|essa|esse)/i.test(t)) return false;
    // Vazamento do system prompt / estrutura interna.
    if (/REGRA CR[IÍ]TICA DE SEGURAN[ÇC]A|<knowledge_base|<identity>|<active_platform>/i.test(t)) return false;
    // Vazamento de raciocínio em inglês NÃO removido pela normalização → rejeita
    // para a cascata tentar outro modelo (rede dupla com normalizeAnswer 4b).
    if (/^\s*(?:okay|alright|let me|first,?\s+i|the user|i need to|i should|i'?ll|we need|i'?m going to|to answer|based on the)\b/i.test(t)) return false;
    return true;
}

// ── Revisor de texto (2ª camada, GATED) ──────────────────────────────────────
// Chamado SÓ quando o reparo determinístico (../_shared/text-repair.ts) ainda
// detecta resíduo suspeito. É best-effort: qualquer falha/recusa/divergência de
// tamanho devolve null e o chamador MANTÉM o texto já reparado (nunca piora).
// Usa o modelo com melhor PT-BR da casa (llama-3.3-70b) em temperatura 0 — tarefa
// de REVISÃO é muito mais simples que geração, então o risco de o revisor "comer"
// espaço é baixo (e, se acontecer, o chamador roda o determinístico de novo por cima).
const PROOFREAD_MODEL = "meta-llama/llama-3.3-70b-instruct:free";
const PROOFREAD_SYSTEM = `Você é um REVISOR de texto em português do Brasil. Sua ÚNICA tarefa é corrigir erros de digitação, ESPAÇAMENTO, ortografia e acentuação, mantendo EXATAMENTE:
- o sentido e as informações (NÃO adicione, NÃO remova, NÃO resuma, NÃO responda nada, NÃO comente);
- o idioma (português) e o tom;
- toda a formatação Markdown, listas, links, quebras de linha e blocos de código (NÃO altere o que está entre crases).
Corrija ESPECIALMENTE palavras grudadas (ex.: "conteúdoacadêmico" -> "conteúdo acadêmico"; "otema" -> "o tema") e espaços faltando após pontuação.
Responda SOMENTE com o texto corrigido — sem aspas, sem prefixos, sem explicações.`;

export async function proofreadAnswer(apiKey: string, text: string): Promise<string | null> {
    const input = (text || "").trim();
    if (input.length < 8) return null; // curto demais p/ valer uma chamada
    try {
        const response = await fetchWithTimeout('https://openrouter.ai/api/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Authorization': "Bearer " + apiKey,
                'Content-Type': 'application/json',
                'HTTP-Referer': LLM.REFERER,
                'X-Title': LLM.TITLE
            },
            body: JSON.stringify({
                model: PROOFREAD_MODEL,
                messages: [
                    { role: "system", content: PROOFREAD_SYSTEM },
                    { role: "user", content: input }
                ],
                temperature: 0,
                max_tokens: Math.min(1200, Math.ceil(input.length / 2) + 200)
            })
        }, LLM.CLASSIFIER_TIMEOUT_MS);

        if (!response.ok) return null;
        const data = await response.json();
        const out = normalizeAnswer(data.choices?.[0]?.message?.content);
        if (!out) return null;
        // Sanidade: revisão NÃO deve mudar drasticamente o tamanho (sinal de que
        // resumiu/respondeu em vez de revisar) nem vazar inglês/recusa.
        if (out.length < input.length * 0.6 || out.length > input.length * 1.8) return null;
        if (!isAcceptableAnswer(out)) return null;
        return out;
    } catch (_e) {
        return null; // best-effort: chamador mantém o texto determinístico
    }
}

export type PedagogicalIntent = "ANALOGY_MODE" | "CHALLENGE_MODE" | "DEFAULT_MODE";

export interface PedagogicalMode {
    intent: PedagogicalIntent;
    reasoning: string;
}

export async function classifyPedagogicalIntent(
    apiKey: string,
    lastMessage: string,
    _history: any[]
): Promise<PedagogicalMode> {
    if (!lastMessage || lastMessage.trim().length === 0) {
        return { intent: "DEFAULT_MODE", reasoning: "Mensagem vazia." };
    }

    const classificationPrompt = `
Analyze the student's last message and classify their pedagogical need.

Categories:
1. CONFUSION_HIGH (Student is lost, says "I don't understand", "Confused", "Hard") -> ANALOGY_MODE
2. MASTERY_HIGH (Student says "Easy", "I know this", "Give me harder stuff") -> CHALLENGE_MODE
3. NEUTRAL (Standard question) -> DEFAULT_MODE

OUTPUT FORMAT (JSON ONLY):
{
  "intent": "ANALOGY_MODE" | "CHALLENGE_MODE" | "DEFAULT_MODE",
  "reasoning": "Brief explanation of why (max 1 sentence)"
}
`;

    try {
        const response = await fetchWithTimeout('https://openrouter.ai/api/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Authorization': "Bearer " + apiKey,
                'Content-Type': 'application/json',
                'HTTP-Referer': LLM.REFERER,
                'X-Title': LLM.TITLE
            },
            body: JSON.stringify({
                model: LLM.CLASSIFIER_MODEL,
                messages: [
                    { role: "system", content: classificationPrompt },
                    { role: "user", content: lastMessage }
                ],
                temperature: LLM.TEMPERATURE_CLASSIFIER,
                max_tokens: LLM.MAX_TOKENS_CLASSIFIER,
                response_format: { type: "json_object" }
            })
        }, LLM.CLASSIFIER_TIMEOUT_MS);

        if (!response.ok) {
            return { intent: "DEFAULT_MODE", reasoning: "Erro na analise (API): " + response.status };
        }

        const data = await response.json();
        const content: string = data.choices?.[0]?.message?.content?.trim() || "";
        const VALID: PedagogicalIntent[] = ["ANALOGY_MODE", "CHALLENGE_MODE", "DEFAULT_MODE"];

        try {
            const parsed = JSON.parse(content);
            const intent: PedagogicalIntent = VALID.includes(parsed?.intent) ? parsed.intent : "DEFAULT_MODE";
            return {
                intent,
                reasoning: parsed?.reasoning || "Analise realizada, mas sem justificativa."
            };
        } catch (_e) {
            // Modelo não devolveu JSON válido — extrai a intenção por palavra-chave.
            if (content.includes("ANALOGY_MODE")) return { intent: "ANALOGY_MODE", reasoning: content.slice(0, 200) };
            if (content.includes("CHALLENGE_MODE")) return { intent: "CHALLENGE_MODE", reasoning: content.slice(0, 200) };
            return { intent: "DEFAULT_MODE", reasoning: content.slice(0, 200) };
        }

    } catch (_e) {
        return { intent: "DEFAULT_MODE", reasoning: "Falha interna no classificador." };
    }
}

// usage: tokens reais + custo (OpenRouter devolve usage.cost com usage.include).
export interface OpenRouterUsage {
    prompt_tokens?: number;
    completion_tokens?: number;
    total_tokens?: number;
    cost?: number;
}

export async function callOpenRouterWithTools(
    apiKey: string,
    messages: any[],
    tools: any[],
    model: string,
    toolChoice: "auto" | "required" = "auto"
): Promise<{ content?: string; tool_calls?: any[]; error?: string; usage?: OpenRouterUsage | null; finish_reason?: string | null }> {
    console.log("[OPENROUTER] Chamando " + model + " com " + tools.length + " tools");

    let response: Response;
    try {
        response = await fetchWithTimeout('https://openrouter.ai/api/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Authorization': "Bearer " + apiKey,
                'Content-Type': 'application/json',
                'HTTP-Referer': LLM.REFERER,
                'X-Title': LLM.TITLE
            },
            body: JSON.stringify({
                model: model,
                messages: messages,
                ...(tools.length > 0 ? { tools, tool_choice: toolChoice } : {}),
                temperature: LLM.TEMPERATURE,
                max_tokens: LLM.MAX_TOKENS,
                usage: { include: true }   // pede tokens + custo no corpo da resposta
            })
        }, LLM.TIMEOUT_MS);
    } catch (e: any) {
        const reason = e?.name === 'AbortError' ? 'timeout' : (e?.message || 'network');
        console.error("[OPENROUTER] Falha de rede em " + model + ": " + reason);
        return { error: "Modelo " + model + " indisponivel: " + reason };
    }

    if (!response.ok) {
        const errorText = await response.text();
        console.error("[OPENROUTER] Erro " + response.status + ": " + safeErrorSnippet(errorText));
        return { error: "Modelo " + model + " falhou: " + response.status };
    }

    const data = await response.json();
    const choice = data.choices?.[0]?.message;

    if (!choice) {
        return { error: "Resposta invalida do modelo" };
    }

    return {
        content: choice.content,
        tool_calls: choice.tool_calls,
        usage: data.usage ?? null,
        finish_reason: data.choices?.[0]?.finish_reason ?? null,
    };
}

