// index.ts - darcy-chat
// Moodle REST API direta + system prompts pedagógicos + sentiment + mastery + mini agent loop

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { getCorsHeaders, MODEL_IDS, LLM, COURSE_DARCY_ENABLED } from "./config.ts";
import { sanitizeForPrompt, createRateLimiter } from "../_shared/security.ts";
import { resolveUserRole, getAcademicContextString } from "./utils/helpers.ts";
import { getSystemPrompt, formatPageContextForPrompt } from "./services/prompts.ts";
import { classifyPedagogicalIntent, callOpenRouterWithTools, normalizeAnswer, isAcceptableAnswer, proofreadAnswer } from "./services/openrouter.ts";
import { repairPortugueseText } from "../_shared/text-repair.ts";
import { buildMoodleKnowledgeBlock } from "../_shared/moodle-knowledge.ts";
import { fetchFullCourseContext, formatCourseContextForPrompt } from "./services/moodle-course.ts";
import { resolveMoodleInstance, fetchMoodleUser, verifyMoodleRole } from "../_shared/moodle.ts";
import { getStudentLearningProfile } from "./services/learning.ts";
import { buildInternalToolDefinitions, executeTool } from "./services/tools.ts";
import type { LLMResult, ModelAttempt } from "../_shared/telemetry.ts";
import { buildTurnRecord, recordTurn } from "../_shared/telemetry.ts";

// Roda uma promessa em background (não atrasa a resposta ao aluno) quando a
// runtime do Edge suportar; senão, fire-and-forget.
function runInBackground(p: Promise<unknown>): void {
    try {
        // @ts-ignore — EdgeRuntime existe no Supabase Edge Functions
        if (typeof EdgeRuntime !== "undefined" && EdgeRuntime?.waitUntil) {
            // @ts-ignore
            EdgeRuntime.waitUntil(p);
            return;
        }
    } catch { /* ignore */ }
    (p as Promise<unknown>).catch(() => {});
}

// ── Rate Limiting (per-instance, IP-based) ──────────────────────────────────
// sanitizeForPrompt + o padrão de rate-limit por chave foram movidos para
// ../_shared/security.ts (US-002). Aqui só instanciamos o limiter do texto com
// os mesmos limites de antes (30 req / 60s por IP).
const RATE_LIMIT = 30; // max requests per window per IP
const RATE_WINDOW_MS = 60_000; // 1 minute
const checkRateLimit = createRateLimiter(RATE_LIMIT, RATE_WINDOW_MS);

// resolveMoodleInstance + a camada de dados Moodle (moodleUrl/fetchMoodleUser/
// verifyMoodleRole) foram movidas para ../_shared/moodle.ts (US-004) e importadas
// acima. O comportamento e identico — apenas MOVER.

// Modelos vêm da fonte única em config.ts (MODEL_IDS). Primário FIXO (não
// auto-roteador) para comportamento reproduzível; a cauda existe para Darcy
// nunca parar de responder. PRIMARY_MODEL = primeiro; FALLBACK = restante.
const PRIMARY_MODEL = MODEL_IDS[0];
const FALLBACK_MODELS = MODEL_IDS.slice(1);

// FEATURE FLAG: Darcy de curso (tutor verde, com tools) — agora fonte única em
// ../_shared/config.ts (COURSE_DARCY_ENABLED), importada acima. No piloto roda
// APENAS o suporte técnico (azul); mantenha false no shared até o lançamento.

// Higiene de log (LGPD): redige o wstoken (e sesskey/token) de qualquer string
// que va para o log — mensagens de erro de fetch podem ecoar a URL do Moodle
// com o token. Usar em TODO console.* que possa conter URL/erro do Moodle.
function stripToken(value: unknown): string {
    const s = value instanceof Error ? (value.message || String(value)) : String(value ?? '');
    return s.replace(/(wstoken|sesskey|token)=[^&\s"']+/gi, '$1=REDACTED');
}

// fetchMoodleUser + verifyMoodleRole foram movidas para ../_shared/moodle.ts
// (US-004) e importadas no topo. Comportamento identico — apenas MOVER.

// ── Extrai nomes de módulos do curso para ancorar mastery ────────────────────

function extractCourseModuleNames(sections: any[]): string[] {
    const names: string[] = [];
    for (const section of sections || []) {
        for (const mod of section.modules || []) {
            if (mod.name && mod.modname !== 'label') {
                names.push(mod.name.trim());
            }
        }
    }
    return names;
}

// ── LLM com fallback + gate de qualidade ─────────────────────────────────────
// Tenta cada modelo da cascata. Uma resposta só é aceita se passar no gate
// (normalizeAnswer + isAcceptableAnswer); caso contrário, tenta o próximo
// modelo. Se NENHUMA passar mas alguma trouxe texto, devolve a melhor reserva
// (best-effort) — Darcy nunca fica mudo enquanto houver qualquer saída.

async function callLLMDirect(apiKey: string, messages: any[]): Promise<LLMResult> {
    // chain = telemetria: registra TODA tentativa (modelo, status, desfecho,
    // latência, tokens) — é o que permite reordenar a cascata com dado real.
    const chain: ModelAttempt[] = [];
    let bestEffort: LLMResult | null = null;

    for (const model of MODEL_IDS) {
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), LLM.TIMEOUT_MS);
        const t0 = Date.now();
        try {
            console.log(`[DARCY] Tentando: ${model}`);
            const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
                method: 'POST',
                signal: ctrl.signal,
                headers: {
                    'Authorization': `Bearer ${apiKey}`,
                    'Content-Type': 'application/json',
                    'HTTP-Referer': LLM.REFERER,
                    'X-Title': LLM.TITLE
                },
                body: JSON.stringify({ model, messages, temperature: LLM.TEMPERATURE, max_tokens: LLM.MAX_TOKENS, stream: false, usage: { include: true } })
            });
            const latency = Date.now() - t0;
            if (!res.ok) {
                console.warn(`[DARCY] ${model} -> ${res.status}`);
                chain.push({ model, status: res.status, outcome: 'http_error', latency_ms: latency });
                continue;
            }
            const data = await res.json();
            const usage = data.usage ?? null;
            const finishReason = data.choices?.[0]?.finish_reason ?? null;
            const content = normalizeAnswer(data.choices?.[0]?.message?.content);
            if (!content) {
                chain.push({ model, status: res.status, outcome: 'empty', latency_ms: latency, prompt_tokens: usage?.prompt_tokens, completion_tokens: usage?.completion_tokens });
                continue;
            }
            if (isAcceptableAnswer(content)) {
                console.log(`[DARCY] OK: ${model}`);
                chain.push({ model, status: res.status, outcome: 'ok', latency_ms: latency, prompt_tokens: usage?.prompt_tokens, completion_tokens: usage?.completion_tokens });
                return { content, model, chain, usage, gatePassed: true, wasBestEffort: false, finishReason };
            }
            // Tem texto mas reprovou no gate (recusa/idioma/eco): guarda como reserva.
            console.warn(`[DARCY] ${model} reprovou no gate de qualidade, tentando próximo`);
            chain.push({ model, status: res.status, outcome: 'gate_failed', latency_ms: latency, prompt_tokens: usage?.prompt_tokens, completion_tokens: usage?.completion_tokens });
            if (!bestEffort) bestEffort = { content, model, chain, usage, gatePassed: false, wasBestEffort: true, finishReason };
        } catch (e: any) {
            const reason = e?.name === 'AbortError' ? 'timeout' : (e?.message || 'erro');
            console.warn(`[DARCY] Erro ${model}: ${reason}`);
            chain.push({ model, status: null, outcome: 'exception', latency_ms: Date.now() - t0 });
        } finally {
            clearTimeout(timer);
        }
    }

    if (bestEffort) {
        console.warn(`[DARCY] Nenhum modelo passou no gate; usando best-effort de ${bestEffort.model}`);
        return { ...bestEffort, chain }; // chain completa (todas as tentativas)
    }
    throw new Error('Todos os modelos falharam');
}

// ── Mini agent loop (in-course: tool calling em até 2 iterações) ─────────────

type AgentResult = LLMResult & { toolCalls: any[]; agentIterations: number };

// Soma usage entre chamadas (pagamos por TODAS as iterações + tool calls).
function mergeUsage(a: any, b: any): any {
    if (!a) return b ? { ...b } : null;
    if (!b) return a;
    return {
        prompt_tokens: (a.prompt_tokens || 0) + (b.prompt_tokens || 0),
        completion_tokens: (a.completion_tokens || 0) + (b.completion_tokens || 0),
        total_tokens: (a.total_tokens || 0) + (b.total_tokens || 0),
        cost: (a.cost || 0) + (b.cost || 0),
    };
}

async function agentLoop(
    apiKey: string,
    messages: any[],
    tools: any[],
    moodleBase: string,
    moodleToken: string,
    supabase: any | null,
    context: any
): Promise<AgentResult> {
    let usedModel = PRIMARY_MODEL;
    const MAX_ITER = 2;
    // Telemetria agregada do loop agêntico
    const chain: ModelAttempt[] = [];
    const toolCallsLog: any[] = [];
    let aggUsage: any = null;
    let lastFinish: string | null = null;

    for (let iter = 0; iter < MAX_ITER; iter++) {
        // Na última iteração remove tools para forçar resposta de texto
        const activeTools = iter < MAX_ITER - 1 ? tools : [];

        console.log(`[AGENT] Iteracao ${iter + 1}/${MAX_ITER} (${activeTools.length} tools)`);
        let tCall = Date.now();
        let result = await callOpenRouterWithTools(apiKey, messages, activeTools, usedModel, 'auto');
        chain.push({ model: usedModel, status: result.error ? null : 200, outcome: result.error ? 'http_error' : 'ok', latency_ms: Date.now() - tCall, prompt_tokens: result.usage?.prompt_tokens, completion_tokens: result.usage?.completion_tokens });
        if (!result.error) { aggUsage = mergeUsage(aggUsage, result.usage); lastFinish = result.finish_reason ?? lastFinish; }

        // Fallback de modelo se falhar
        if (result.error) {
            for (const fallback of FALLBACK_MODELS) {
                console.warn(`[AGENT] Fallback para ${fallback}`);
                tCall = Date.now();
                result = await callOpenRouterWithTools(apiKey, messages, activeTools, fallback, 'auto');
                chain.push({ model: fallback, status: result.error ? null : 200, outcome: result.error ? 'http_error' : 'ok', latency_ms: Date.now() - tCall, prompt_tokens: result.usage?.prompt_tokens, completion_tokens: result.usage?.completion_tokens });
                if (!result.error) { usedModel = fallback; aggUsage = mergeUsage(aggUsage, result.usage); lastFinish = result.finish_reason ?? lastFinish; break; }
            }
        }

        if (result.error || !result) {
            return { content: 'Nao consegui processar sua solicitacao no momento. Tente novamente.', model: usedModel, chain, usage: aggUsage, gatePassed: false, wasBestEffort: true, finishReason: lastFinish, toolCalls: toolCallsLog, agentIterations: iter + 1 };
        }

        // Sem tool calls: resposta final
        if (!result.tool_calls || result.tool_calls.length === 0) {
            const content = (result.content || '').trim();
            if (content) return { content, model: usedModel, chain, usage: aggUsage, gatePassed: true, wasBestEffort: false, finishReason: lastFinish, toolCalls: toolCallsLog, agentIterations: iter + 1 };
            // conteúdo vazio — força próxima iteração sem tools
            continue;
        }

        // Executa tools em paralelo
        console.log(`[AGENT] ${result.tool_calls.length} tool(s) chamada(s)`);
        messages = [
            ...messages,
            { role: 'assistant', content: result.content || null, tool_calls: result.tool_calls }
        ];

        const toolResults = await Promise.all(
            result.tool_calls.map(async (tc: any) => {
                // Free models às vezes emitem argumentos malformados — não deixe
                // um JSON inválido derrubar a request inteira; devolve erro ao modelo.
                let args: any = {};
                try {
                    args = JSON.parse(tc.function?.arguments || '{}');
                } catch (_e) {
                    toolCallsLog.push({ name: tc.function?.name || 'unknown', ok: false });
                    return { role: 'tool', tool_call_id: tc.id, content: JSON.stringify({ error: 'argumentos inválidos (JSON malformado)' }) };
                }
                const toolResult = await executeTool(
                    tc.function.name,
                    args,
                    moodleBase,
                    moodleToken,
                    supabase,
                    context
                );
                toolCallsLog.push({ name: tc.function?.name || 'unknown', ok: true });
                return { role: 'tool', tool_call_id: tc.id, content: JSON.stringify(toolResult) };
            })
        );

        messages = [...messages, ...toolResults];
    }

    // Se chegou aqui sem resposta, faz chamada direta sem tools
    const final = await callLLMDirect(apiKey, messages);
    return { ...final, chain: [...chain, ...final.chain], usage: mergeUsage(aggUsage, final.usage), toolCalls: toolCallsLog, agentIterations: MAX_ITER };
}

// ── Handler ───────────────────────────────────────────────────────────────────

Deno.serve(async (req) => {
    // ── CORS: whitelist Moodle origins (must match on OPTIONS AND POST) ──
    const origin = req.headers.get('origin') || '';
    const dynCors = getCorsHeaders(origin);

    if (req.method === 'OPTIONS') return new Response(null, { headers: dynCors });

    // ── Rate Limiting ──
    const clientIp = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown';
    if (!checkRateLimit(clientIp)) {
        return new Response(JSON.stringify({ error: 'Rate limit exceeded. Try again in 1 minute.' }), {
            status: 429,
            headers: { ...dynCors, 'Content-Type': 'application/json', 'Retry-After': '60' },
        });
    }

    // ── Telemetria: id do turno + escopo externo p/ registrar até turnos de erro ──
    const turnId = crypto.randomUUID();
    let supabaseTel: any = null;
    let errorTurnMeta: any = null; // preenchido ao longo do try; permite gravar turno de erro no catch

    try {
        const { message, conversation = [], context, telemetry } = await req.json();
        const tel = telemetry || {};

        // SECURITY: Truncate message to prevent cost amplification
        const safeMessage = (message || '').slice(0, 2000);

        const openRouterKey = Deno.env.get('OPENROUTER_API_KEY');
        const supabaseUrl = Deno.env.get('SUPABASE_URL');
        const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');

        if (!openRouterKey) throw new Error('OPENROUTER_API_KEY não configurado');

        const effectiveContext = context || {};

        // KILL-SWITCH do Darcy de curso (feature futura): independente do que o
        // cliente enviar, força modo SUPORTE anulando o courseId. Isso é a fonte
        // de verdade no servidor — o getSystemPrompt e o caminho de tools re-derivam
        // o modo a partir do courseId, então zerar aqui desliga tudo de uma vez.
        if (!COURSE_DARCY_ENABLED) {
            effectiveContext.courseId = null;
            effectiveContext.type = 'general';
        }

        // Resolve which Moodle instance to use based on widget origin URL
        const moodleInstance = resolveMoodleInstance(effectiveContext.url);
        const moodleBase = moodleInstance.base;
        const moodleToken = moodleInstance.token;
        console.log(`[DARCY] Moodle instance: ${moodleBase} (token: ${moodleToken ? 'present' : 'MISSING'})`);
        const userId = effectiveContext.userId ? String(effectiveContext.userId) : null;
        const courseId = effectiveContext.courseId ? String(effectiveContext.courseId) : null;
        const isCourseCtx = !!(courseId && courseId !== 'null' && courseId !== 'undefined');
        const role = resolveUserRole(effectiveContext);

        // SECURITY: Override client-supplied role with server-verified role
        let verifiedRole = role;
        if (userId && courseId && moodleToken) {
            verifiedRole = await verifyMoodleRole(moodleBase, moodleToken, userId, String(courseId));
            console.log(`[DARCY] Role verified: client=${role} server=${verifiedRole}`);
            // Inject verified role into context so downstream resolveUserRole() calls use it
            effectiveContext.userRole = verifiedRole;
            effectiveContext.userRoleIds = verifiedRole === 'teacher' ? [3] : [5];
        }

        console.log(`[DARCY] userId=${userId} courseId=${courseId} role=${verifiedRole}`);

        // Inicializa Supabase (para mastery)
        const supabase = (supabaseUrl && supabaseServiceKey)
            ? createClient(supabaseUrl, supabaseServiceKey)
            : null;
        supabaseTel = supabase;

        // ── Busca em paralelo: dados do usuário + contexto completo do curso + classificação pedagógica ──

        const userPromise = (moodleToken && userId)
            ? fetchMoodleUser(moodleBase, moodleToken, userId, courseId)
            : Promise.resolve({ userData: null, coursesData: null });

        const courseCtxPromise = (moodleToken && isCourseCtx)
            ? fetchFullCourseContext(moodleBase, moodleToken, Number(courseId), userId ? Number(userId) : null)
            : Promise.resolve(null);

        const pedagogicalPromise = (isCourseCtx && verifiedRole === 'student')
            ? classifyPedagogicalIntent(openRouterKey, safeMessage, conversation)
            : Promise.resolve({ intent: 'DEFAULT_MODE' as const, reasoning: '' });

        const [moodleUser, fullCourseCtx, pedagogicalMode] = await Promise.all([
            userPromise, courseCtxPromise, pedagogicalPromise
        ]);

        // Perfil de aprendizagem do aluno (histórico de mastery do Supabase)
        const learningProfile = (supabase && userId && isCourseCtx && verifiedRole === 'student')
            ? await getStudentLearningProfile(supabase, userId, courseId!)
            : null;

        // ── Constrói contexto acadêmico ──────────────────────────────────────

        let academicContext = '';
        if (moodleUser.userData || moodleUser.coursesData) {
            academicContext = getAcademicContextString(
                moodleUser.userData, moodleUser.coursesData, verifiedRole, undefined, courseId
            );
            console.log(`[DARCY] academicContext: ${academicContext.length} chars`);
        }

        if (isCourseCtx) {
            console.log(`[DARCY] Pedagogia: ${pedagogicalMode.intent} — ${pedagogicalMode.reasoning}`);
            if (learningProfile) console.log(`[DARCY] Learning profile carregado`);
        }

        const courseContext = fullCourseCtx ? formatCourseContextForPrompt(fullCourseCtx) : '';

        // Nomes dos módulos do curso para ancorar mastery
        const courseModuleNames = fullCourseCtx
            ? extractCourseModuleNames(fullCourseCtx.sections)
            : [];

        // ── System prompt ────────────────────────────────────────────────────

        const systemPrompt = getSystemPrompt(
            effectiveContext,
            learningProfile,
            pedagogicalMode,
            academicContext,
            courseContext,
            moodleBase
        );

        // ── Context Engineering: Conversation Window Management ─────────────
        // Regras:
        // 1. Filtrar mensagens inválidas
        // 2. Manter últimas 10 trocas (20 mensagens) — janela deslizante
        // 3. Limpar thinking tags de mensagens anteriores do assistant
        // 4. Sistema → conversa → mensagem atual (proximity bias: dados recentes perto do fim)

        const validConv = Array.isArray(conversation)
            ? conversation
                // Allowlist de papéis: só user/assistant do cliente entram no histórico.
                // (Impede um cliente forjado de injetar role:'system'/'tool'.)
                .filter((m: any) => (m?.role === 'user' || m?.role === 'assistant') && typeof m?.content === 'string' && m.content.trim())
                .map((m: any) => ({
                    role: m.role,
                    content: m.role === 'assistant' ? normalizeAnswer(m.content) : m.content
                }))
                .filter((m: any) => m.content) // remove vazios após normalização
                .slice(-20) // últimas 20 mensagens (10 trocas)
            : [];

        // ── Context Engineering: Page Context Injection ──────────────────────
        // O pageContext descreve ONDE o usuário está e O QUE ele vê na tela.
        // Injetado como prefixo da mensagem do usuário (proximity bias máximo).

        // Sanitize page context to prevent prompt injection
        const safePageContext = effectiveContext?.pageContext ? {
            ...effectiveContext.pageContext,
            pageTitle: sanitizeForPrompt(effectiveContext.pageContext.pageTitle),
            pageHeading: sanitizeForPrompt(effectiveContext.pageContext.pageHeading),
            breadcrumb: Array.isArray(effectiveContext.pageContext.breadcrumb)
                ? effectiveContext.pageContext.breadcrumb.map((b: string) => sanitizeForPrompt(b)).slice(0, 5)
                : [],
            visibleContent: sanitizeForPrompt(effectiveContext.pageContext.visibleContent),
            alerts: Array.isArray(effectiveContext.pageContext.alerts)
                ? effectiveContext.pageContext.alerts.map((a: string) => sanitizeForPrompt(a)).slice(0, 3)
                : [],
            activityName: sanitizeForPrompt(effectiveContext.pageContext.activityName),
            sectionName: sanitizeForPrompt(effectiveContext.pageContext.sectionName),
        } : effectiveContext?.pageContext;

        const pageContextStr = formatPageContextForPrompt(safePageContext);
        // SECURITY: Sanitize user message to strip injection attempts (but don't truncate — already capped at 2000)
        const sanitizedMessage = safeMessage
            .replace(/\[MENSAGEM DO USU[AÁ]RIO\]/gi, '[contexto]')
            .replace(/\[SYSTEM\]/gi, '[contexto]')
            .replace(/\[INSTRU[CÇ][AÃ]O\]/gi, '[contexto]')
            .replace(/<\/?(?:system|user|assistant|instruction|prompt|thinking|thought)>/gi, '')
            .replace(/ignore\s+(?:all\s+)?(?:previous|above|prior)\s+instructions?/gi, '[filtrado]')
            .replace(/you\s+are\s+now\s+/gi, '[filtrado]')
            .replace(/reveal\s+(?:your\s+)?(?:system\s+)?prompt/gi, '[filtrado]');
        const userMessage = pageContextStr
            ? pageContextStr + "\n\n[MENSAGEM DO USUÁRIO]\n" + sanitizedMessage
            : sanitizedMessage;

        // ── Conhecimento do MOODLE (domínio do produto) ──────────────────────
        // Índice-núcleo (todas as áreas) SEMPRE + detalhe das 1–2 seções relevantes
        // à pergunta/página, via roteador determinístico por palavra-chave (sem RAG/
        // vetor). Faz o Darcy orientar "onde clicar" em qualquer função do Moodle.
        const moodleKnowledge = buildMoodleKnowledgeBlock(sanitizedMessage, safePageContext, verifiedRole);
        const systemPromptFull = systemPrompt + "\n\n" + moodleKnowledge;

        const messages = [
            { role: 'system', content: systemPromptFull },
            ...validConv,
            { role: 'user', content: userMessage }
        ];

        // ── Resposta: mini agent loop (in-course) ou chamada direta (área geral) ──

        let response: string;
        let model: string;
        let llmResult: LLMResult;
        let turnToolCalls: any[] = [];
        let turnAgentIterations = 0;

        // Metadados mínimos para registrar até um turno de ERRO no catch.
        let moodleOrigin: string | null = null;
        try { moodleOrigin = effectiveContext.url ? new URL(String(effectiveContext.url)).hostname : null; } catch { /* url inválida */ }
        errorTurnMeta = {
            conversationId: tel.conversation_id ?? null,
            sessionId: tel.session_id ?? null,
            turnIndex: tel.turn_index ?? null,
            browserId: tel.browser_id ?? null,
            moodleUserId: userId ? Number(userId) : null,
            darcyMode: isCourseCtx ? 'course' : 'support',
            verifiedRole,
            courseId: courseId ? Number(courseId) : null,
            moodleOrigin,
            userMessage: safeMessage,
        };

        const turnStart = Date.now();

        if (isCourseCtx && moodleToken) {
            const tools = buildInternalToolDefinitions(!!supabase, effectiveContext, courseModuleNames);
            console.log(`[DARCY] Agent loop com ${tools.length} tools, ${courseModuleNames.length} modulos`);
            const result = await agentLoop(
                openRouterKey, messages, tools,
                moodleBase, moodleToken, supabase, effectiveContext
            );
            llmResult = result;
            turnToolCalls = result.toolCalls;
            turnAgentIterations = result.agentIterations;
            response = result.content;
            model = result.model;
        } else {
            const result = await callLLMDirect(openRouterKey, messages);
            llmResult = result;
            response = result.content;
            model = result.model;
        }
        const turnLatencyMs = Date.now() - turnStart;

        // ── Limpeza final da resposta ────────────────────────────────────────
        // Normaliza a saída (think tags, rótulos de papel, cercas) — necessário
        // sobretudo para o caminho de tools, cujo conteúdo ainda vem cru.
        response = normalizeAnswer(response);

        // Rede de segurança: se ficou vazia (ex.: modelo só emitiu raciocínio que
        // foi removido), entrega uma mensagem amigável em vez de resposta em branco.
        if (!response) {
            console.warn('[DARCY] Resposta vazia após normalização');
            response = 'Desculpe, não consegui gerar uma resposta adequada. Pode reformular sua pergunta?';
        }

        // ── CAMADA DE REPARO DE TEXTO (determinístico + revisor IA gated) ─────
        // Os modelos :free às vezes cospem PT com espaços faltando
        // ("conteúdo acadêmico" -> "conteúdoacadêmico", "o tema" -> "otema").
        // NUNCA deixamos texto cru chegar ao aluno: (1) reparo determinístico
        // SEMPRE (grátis, instantâneo, separa palavras grudadas via léxico PT-BR +
        // conserta espaçamento de pontuação); (2) SÓ quando ainda sobra resíduo
        // suspeito, uma revisão por IA best-effort (com fallback pro texto já
        // reparado, então nunca piora). É o mesmo texto que vai pro widget E pra
        // telemetria (capturada mais abaixo a partir de `response`).
        const repaired = repairPortugueseText(response);
        response = repaired.text;
        if (repaired.suspicious) {
            console.log('[DARCY] Resíduo suspeito no texto — acionando revisão por IA');
            const polished = await proofreadAnswer(openRouterKey, response);
            if (polished) response = repairPortugueseText(polished).text;
        }

        // Extrair dados do usuário do Moodle
        const userData = moodleUser?.userData;
        const userList = Array.isArray(userData?.users) ? userData.users : Array.isArray(userData) ? userData : [];
        const mUser = userList[0] || null;

        // SERVER-SIDE: Enrich user profile in DB directly
        if (supabase && mUser && userId) {
            const mId = Number(mUser.id || userId);
            if (mId > 1) { // Skip guest user (id=1)
                try {
                    const profileData = {
                        moodle_user_id: mId,
                        moodle_username: mUser.username || undefined,
                        moodle_email: mUser.email || undefined,
                        moodle_full_name: mUser.fullname || (mUser.firstname && mUser.lastname ? `${mUser.firstname} ${mUser.lastname}` : undefined) || undefined,
                        moodle_idnumber: mUser.idnumber || undefined,
                        moodle_phone1: mUser.phone1 || undefined,
                        moodle_city: mUser.city || undefined,
                        moodle_institution: mUser.institution || undefined,
                        last_access: new Date().toISOString(),
                        updated_at: new Date().toISOString(),
                    };

                    await supabase.from('users').upsert(profileData, { onConflict: 'moodle_user_id' }).catch(() => {});
                    console.log(`[DARCY] User profile enriched: moodle_id=${mId}`);
                } catch (e) {
                    console.warn('[DARCY] User enrichment failed:', stripToken(e));
                }
            }
        }

        // User profile returned to widget — apenas dados necessários para exibição.
        // PII sensível (email, phone1, idnumber, city, institution) fica server-side
        // (já armazenado em `users` via upsert acima); não trafega para o browser.
        const userProfile = mUser ? {
            moodle_user_id: mUser.id || userId,
            username: mUser.username || null,
            full_name: mUser.fullname || (mUser.firstname && mUser.lastname ? `${mUser.firstname} ${mUser.lastname}` : null),
        } : null;

        // ── TELEMETRIA: grava o turno canônico em background ─────────────────
        // Resolve user_id + consentimento e persiste SEM atrasar a resposta.
        // É o ponto de captura autoritativo (tem system prompt, janela, usage,
        // cadeia de fallback e gate — tudo que o widget não vê).
        const fullNameForRedaction = mUser?.fullname
            || (mUser?.firstname && mUser?.lastname ? `${mUser.firstname} ${mUser.lastname}` : null);
        const conversationWindowSent = messages.slice(1); // tudo menos o system prompt

        runInBackground((async () => {
            try {
                let userUuid: string | null = null;
                const mid = mUser?.id ? Number(mUser.id) : (userId ? Number(userId) : null);
                if (supabase && mid && mid > 1) {
                    const { data: u } = await supabase.from('users').select('id').eq('moodle_user_id', mid).single();
                    userUuid = u?.id ?? null;
                }
                if (!userUuid && supabase && tel.browser_id) {
                    const { data: u } = await supabase.from('users').select('id').eq('browser_id', tel.browser_id).single();
                    userUuid = u?.id ?? null;
                }
                // Consentimento (opt-out sobre base legal aprovada)
                let contentConsent = true;
                if (supabase && userUuid) {
                    const { data: c } = await supabase.rpc('has_training_consent', { p_user_id: userUuid });
                    if (c === false) contentConsent = false;
                }

                const rec = buildTurnRecord({
                    turnId,
                    conversationId: tel.conversation_id ?? null,
                    sessionId: tel.session_id ?? null,
                    turnIndex: tel.turn_index ?? null,
                    userId: userUuid,
                    moodleUserId: mid,
                    browserId: tel.browser_id ?? null,
                    moodleOrigin,
                    darcyMode: isCourseCtx ? 'course' : 'support',
                    verifiedRole,
                    courseId: courseId ? Number(courseId) : null,
                    userMessage: safeMessage,
                    assistantMessage: response,
                    systemPrompt: systemPromptFull,
                    conversationWindow: conversationWindowSent,
                    userFullName: fullNameForRedaction,
                    contentConsent,
                    llm: llmResult,
                    temperature: LLM.TEMPERATURE,
                    maxTokens: LLM.MAX_TOKENS,
                    pedagogicalIntent: isCourseCtx ? pedagogicalMode.intent : null,
                    pedagogicalReasoning: isCourseCtx ? pedagogicalMode.reasoning : null,
                    toolCalls: turnToolCalls,
                    agentIterations: turnAgentIterations,
                    academicContextChars: academicContext ? academicContext.length : null,
                    courseContextChars: courseContext ? courseContext.length : null,
                    pageContext: safePageContext ?? null,
                    latencyMs: turnLatencyMs,
                });
                await recordTurn(supabase, rec);
            } catch (e: any) {
                console.warn('[TELEMETRY] persistTurn falhou:', e?.message || e);
            }
        })());

        return new Response(JSON.stringify({ response, model, userProfile, turn_id: turnId }), {
            headers: { ...dynCors, 'Content-Type': 'application/json' }
        });

    } catch (error) {
        // Higiene de log (LGPD): a mensagem de erro de um fetch ao Moodle pode
        // ecoar a URL com wstoken — redige antes de logar.
        console.error('[DARCY] Erro:', stripToken(error));

        // TELEMETRIA: registra o turno de ERRO (metadados; sem conteúdo) para
        // sabermos QUANDO e por quê Darcy falhou — sinal de qualidade essencial.
        if (supabaseTel && errorTurnMeta) {
            const m = errorTurnMeta;
            const errRec = buildTurnRecord({
                turnId,
                conversationId: m.conversationId,
                sessionId: m.sessionId,
                turnIndex: m.turnIndex,
                userId: null,
                moodleUserId: m.moodleUserId,
                browserId: m.browserId,
                moodleOrigin: m.moodleOrigin,
                darcyMode: m.darcyMode || 'support',
                verifiedRole: m.verifiedRole ?? null,
                courseId: m.courseId ?? null,
                userMessage: m.userMessage || '',
                assistantMessage: '',
                systemPrompt: '',
                conversationWindow: [],
                contentConsent: false,
                llm: null,
                latencyMs: 0,
                isErrorTurn: true,
                errorDetail: (error instanceof Error ? error.message : String(error)).slice(0, 500),
            });
            runInBackground(recordTurn(supabaseTel, errRec));
        }

        return new Response(JSON.stringify({
            response: 'Peço desculpas, estou com dificuldades técnicas. Tente novamente.',
            error: 'temporary_unavailable',
            turn_id: turnId
        }), { headers: { ...dynCors, 'Content-Type': 'application/json' }, status: 200 });
    }
});

