/**
 * Formata o pageContext capturado pelo widget em texto estruturado para injetar no prompt.
 * Usa proximity bias: este bloco vai junto com a mensagem do usuário para máxima atenção do modelo.
 */
export function formatPageContextForPrompt(pageContext: any): string {
    if (!pageContext) return "";

    const parts: string[] = [];
    parts.push("[CONTEXTO DA PÁGINA ATUAL DO USUÁRIO]");

    if (pageContext.pageType && pageContext.pageType !== 'unknown') {
        const typeLabels: Record<string, string> = {
            dashboard: "Painel principal (Dashboard)",
            course_home: "Página inicial do curso",
            activity: "Atividade do curso",
            quiz: "Questionário/Prova",
            forum: "Fórum de discussão",
            assignment: "Tarefa/Trabalho para envio",
            grades: "Página de notas",
            profile: "Perfil do usuário",
            admin: "Área administrativa",
            login: "Página de login",
            site_home: "Página inicial do Moodle",
        };
        parts.push("Tipo de página: " + (typeLabels[pageContext.pageType] || pageContext.pageType));
    }

    if (pageContext.pageTitle) {
        parts.push("Título: " + pageContext.pageTitle);
    }

    if (pageContext.breadcrumb && pageContext.breadcrumb.length > 0) {
        parts.push("Caminho de navegação: " + pageContext.breadcrumb.join(" → "));
    }

    if (pageContext.pageHeading) {
        parts.push("Cabeçalho principal: " + pageContext.pageHeading);
    }

    if (pageContext.activityType) {
        const activityLabels: Record<string, string> = {
            assign: "Tarefa (envio de trabalho)",
            quiz: "Questionário",
            forum: "Fórum",
            resource: "Recurso/Arquivo",
            page: "Página de conteúdo",
            url: "Link externo",
            folder: "Pasta de arquivos",
            label: "Rótulo",
            book: "Livro",
            glossary: "Glossário",
            wiki: "Wiki",
            choice: "Enquete/Escolha",
            feedback: "Feedback",
            lesson: "Lição",
            workshop: "Workshop",
            scorm: "Pacote SCORM",
            h5pactivity: "H5P (conteúdo interativo)",
            bigbluebuttonbn: "BigBlueButton (videoconferência)",
        };
        parts.push("Tipo de atividade: " + (activityLabels[pageContext.activityType] || pageContext.activityType));
    }

    if (pageContext.activityName) {
        parts.push("Nome da atividade: " + pageContext.activityName);
    }

    if (pageContext.sectionName) {
        parts.push("Seção/Tópico: " + pageContext.sectionName);
    }

    if (pageContext.dueDate) {
        parts.push("Prazo visível: " + pageContext.dueDate);
    }

    if (pageContext.gradeInfo) {
        parts.push("Nota visível: " + pageContext.gradeInfo);
    }

    if (pageContext.hasFileUpload) {
        parts.push("A página tem área de upload de arquivo");
    }

    if (pageContext.alerts && pageContext.alerts.length > 0) {
        parts.push("Alertas/Avisos na tela: " + pageContext.alerts.join(" | "));
    }

    if (pageContext.visibleContent) {
        parts.push("Conteúdo visível (resumo): " + pageContext.visibleContent);
    }

    if (pageContext.navItems && pageContext.navItems.length > 0) {
        parts.push("Menu de navegação: " + pageContext.navItems.join(", "));
    }

    if (parts.length <= 1) return ""; // só tem o header

    return parts.join("\n");
}


