1	// text-repair.ts — Camada DETERMINÍSTICA de reparo de texto PT-BR.
2	//
3	// PROBLEMA: os modelos :free (nemotron/qwen/llama) às vezes cospem português com
4	// espaços faltando — "conteúdo acadêmico" -> "conteúdoacadêmico", "o tema" -> "otema",
5	// "direta e" -> "diretae", "é a" -> "éa". Não dá pra trocar os modelos, então
6	// consertamos a SAÍDA antes de mandar pro aluno. Esta camada NÃO usa IA: é regex +
7	// um léxico PT-BR (pt-dictionary.ts) que separa palavras grudadas COM SEGURANÇA.
8	//
9	// SEGURANÇA (não estragar texto certo): só dividimos um token quando (a) o token
10	// inteiro NÃO está no léxico E (b) existe uma partição em que CADA pedaço está no
11	// léxico. Como as palavras comuns estão no léxico, palavras legítimas ficam
12	// protegidas (ex.: "aprender" está no léxico -> nunca vira "a prender"). Código,
13	// inline-code, URLs e e-mails são preservados intactos.
14	//
15	// Retorna { text, suspicious }: `suspicious=true` sinaliza que SOBROU algo provável
16	// de corrupção que o determinístico não resolveu — o chamador pode então acionar a
17	// passada de revisão por IA (gated). Em texto normal, `suspicious` fica false e
18	// nenhuma IA extra é chamada.
19	
20	import { PT_WORDS } from "./pt-dictionary.ts";
21	
22	// Palavras de 1 letra VÁLIDAS em PT (o léxico só tem tokens >=2; estas entram aqui).
23	// Lista fechada de propósito: NÃO incluir "i/s/t/x..." (ruído do corpus) senão
24	// dividiríamos palavras legítimas letra a letra.
25	const ONE_CHAR_WORDS = new Set(["a", "e", "o", "é", "à"]);
26	
27	// PALAVRAS-FUNÇÃO (classe fechada, 1–2 letras). Só ESTAS podem ser o pedaço "curto"
28	// de uma divisão. Sem isto, "login" (ausente do léxico) viraria "lo"+"gin" (ambos no
29	// corpus). Como "lo"/"gin" não são palavras-função, a divisão é barrada e "login"
30	// fica intacto; já "o tema"/"de curso"/"é a" passam (o/de/é são palavras-função).
31	const FUNCTION_WORDS = new Set([
32	    "a", "e", "o", "é", "à",
33	    "de", "do", "da", "em", "no", "na", "um", "ao", "ou", "se", "os", "as", "me", "te", "às",
34	]);
35	
36	// Estrangeirismos/termos de domínio comuns no suporte Moodle que NÃO estão no corpus
37	// de frequência PT — registramos aqui para (a) nunca serem divididos e (b) servirem
38	// de pedaço válido numa divisão. Defesa extra além da regra de palavras-função.
39	const EXTRA_WORDS = new Set([
40	    "login", "logins", "logout", "email", "emails", "online", "offline", "site", "sites",
41	    "link", "links", "web", "internet", "upload", "download", "app", "apps", "status",
42	    "moodle", "feedback", "quiz", "quizzes", "url", "urls", "pdf", "pdfs", "wifi", "tablet",
43	    "smartphone", "notebook", "desktop", "browser", "cookies", "backup", "chat", "chats",
44	]);
45	
46	// Um pedaço é "léxico" se: 1 letra -> está na allowlist; >=2 letras -> está no PT_WORDS
47	// (corpus de frequência) ou no EXTRA_WORDS (estrangeirismos de domínio).
48	function inLexicon(seg: string): boolean {
49	    if (seg.length === 1) return ONE_CHAR_WORDS.has(seg);
50	    return PT_WORDS.has(seg) || EXTRA_WORDS.has(seg);
51	}
52	
53	const MAX_SEGMENTS = 3;          // glue real raramente é >3 palavras; acima disso, suspeito de retalhar palavra real
54	const MAX_SPLIT_LEN = 40;        // não tenta segmentar tokens gigantes (limita custo da DP)
55	const SUSPICIOUS_LEN = 16;       // token alfabético desconhecido >= isto e não-segmentável -> sinaliza revisão IA
56	
57	// Word-break (programação dinâmica): menor nº de segmentos do léxico que cobre `s`
58	// inteiro, ou null. Prefere palavras LONGAS (tenta j do fim pro início) -> menos
59	// segmentos e particionamento mais natural ("conteúdoacadêmico" -> conteúdo+acadêmico,
60	// não con+teú+do+...). `s` deve estar em minúsculas.
61	function segment(s: string): string[] | null {
62	    const n = s.length;
63	    const memo = new Map<number, string[] | null>();
64	    function go(i: number): string[] | null {
65	        if (i === n) return [];
66	        const cached = memo.get(i);
67	        if (cached !== undefined) return cached;
68	        let best: string[] | null = null;
69	        for (let j = n; j > i; j--) {
70	            const part = s.slice(i, j);
71	            if (!inLexicon(part)) continue;
72	            const rest = go(j);
73	            if (rest === null) continue;
74	            const cand = [part, ...rest];
75	            if (best === null || cand.length < best.length) best = cand;
76	        }
77	        memo.set(i, best);
78	        return best;
79	    }
80	    return go(0);
81	}
82	
83	// Decide a partição de UM token (run de letras). Devolve o token reescrito com
84	// espaços, ou null se não há divisão segura (chamador mantém o original).
85	// `original` preserva caixa/acentos; segmentamos a versão minúscula e recortamos
86	// o original pelos mesmos offsets (toLowerCase preserva o comprimento em PT/latim).
87	function splitGluedToken(original: string): string | null {
88	    if (original.length < 2 || original.length > MAX_SPLIT_LEN) return null;
89	    // Acrônimos em CAIXA ALTA (CPF, CEAD; "UnB" não é all-caps) ficam intactos.
90	    if (original.length > 1 && original === original.toUpperCase()) return null;
91	    const lower = original.toLowerCase();
92	    if (inLexicon(lower)) return null;                 // já é palavra válida -> não toca
93	
94	    const segs = segment(lower);
95	    if (!segs || segs.length < 2 || segs.length > MAX_SEGMENTS) return null;
96	
97	    // Guarda anti-retalho (evita estragar palavra legítima/estrangeira ausente do
98	    // léxico, ex.: "login" -> "lo gin"):
99	    //  - TODO pedaço curto (<=2 letras) precisa ser PALAVRA-FUNÇÃO; e
100	    //  - precisa haver ao menos um pedaço "longo" (>=3 letras),
101	    //    EXCETO o caso legítimo de duas palavras de 1 letra grudadas ("é a" -> "éa").
102	    const allOneChar = segs.length === 2 && segs.every((p) => p.length === 1);
103	    const shortsAllFunction = segs.filter((p) => p.length <= 2).every((p) => FUNCTION_WORDS.has(p));
104	    const hasLong = segs.some((p) => p.length >= 3);
105	    if (!shortsAllFunction) return null;
106	    if (!hasLong && !allOneChar) return null;
107	
108	    // Recorta o ORIGINAL pelos comprimentos dos segmentos (preserva caixa/acentos).
109	    const parts: string[] = [];
110	    let off = 0;
111	    for (const seg of segs) {
112	        parts.push(original.slice(off, off + seg.length));
113	        off += seg.length;
114	    }
115	    return parts.join(" ");
116	}
117	
118	// ── Proteção de regiões que NÃO podem ser tocadas (código, URLs, e-mails) ───────
119	// Sentinela = par de chars da Área de Uso Privado do Unicode (U+E000 / U+E001,
120	// categoria Co — NÃO são letras nem pontuação) com o índice em dígitos no meio.
121	// Assim o placeholder sobrevive intacto às regex de pontuação e de de-aglutinação
122	// (\p{L}+ não casa PUA nem dígitos) e é restaurável sem ambiguidade.
123	interface Protected { text: string; tokens: string[]; }
124	const PH_OPEN = "";
125	const PH_CLOSE = "";
126	
127	function protect(text: string): Protected {
128	    const tokens: string[] = [];
129	    const stash = (m: string): string => {
130	        tokens.push(m);
131	        return `${PH_OPEN}${tokens.length - 1}${PH_CLOSE}`;
132	    };
133	    let t = text;
134	    t = t.replace(/```[\s\S]*?```/g, stash);                  // blocos de código cercados
135	    t = t.replace(/`[^`\n]*`/g, stash);                       // inline code
136	    t = t.replace(/!?\[[^\]]*\]\([^)]*\)/g, stash);           // links/imagens markdown (alvo + url)
137	    t = t.replace(/\b(?:https?:\/\/|www\.)[^\s)]+/gi, stash);  // URLs cruas
138	    t = t.replace(/\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g, stash);     // e-mails
139	    return { text: t, tokens };
140	}
141	function restore(text: string, tokens: string[]): string {
142	    return text.replace(/(\d+)/g, (_m, i) => tokens[Number(i)] ?? "");
143	}
144	
145	// ── Correções de ESPAÇAMENTO em torno de pontuação (fora de código) ────────────
146	function fixPunctuationSpacing(text: string): string {
147	    let t = text;
148	    // Vírgula/;/:/!/? grudados na PRÓXIMA palavra (letra). Lookahead exige LETRA,
149	    // então "1,5" e "12:30" (dígito após) ficam intactos.
150	    t = t.replace(/([,;:!?])(?=[A-Za-zÀ-ÿ])/g, "$1 ");
151	    // Ponto final grudado: só quando minúscula + "." + MAIÚSCULA ("passo.Dúvidas").
152	    // Evita decimais ("3.14": dígito) e siglas ("U.S": maiúscula antes).
153	    t = t.replace(/([a-zà-ÿ])\.([A-ZÀ-Þ])/g, "$1. $2");
154	    // Reticências grudadas em letra.
155	    t = t.replace(/(\.{3}|…)(?=[A-Za-zÀ-ÿ])/g, "$1 ");
156	    // Espaços horizontais duplicados criados pelos passos acima (não mexe em \n).
157	    t = t.replace(/[^\S\n]{2,}/g, " ");
158	    return t;
159	}
