// text-repair.ts — Camada DETERMINÍSTICA de reparo de texto PT-BR.
//
// PROBLEMA: os modelos :free (nemotron/qwen/llama) às vezes cospem português com
// espaços faltando — "conteúdo acadêmico" -> "conteúdoacadêmico", "o tema" -> "otema",
// "direta e" -> "diretae", "é a" -> "éa". Não dá pra trocar os modelos, então
// consertamos a SAÍDA antes de mandar pro aluno. Esta camada NÃO usa IA: é regex +
// um léxico PT-BR (pt-dictionary.ts) que separa palavras grudadas COM SEGURANÇA.
//
// SEGURANÇA (não estragar texto certo): só dividimos um token quando (a) o token
// inteiro NÃO está no léxico E (b) existe uma partição em que CADA pedaço está no
// léxico. Como as palavras comuns estão no léxico, palavras legítimas ficam
// protegidas (ex.: "aprender" está no léxico -> nunca vira "a prender"). Código,
// inline-code, URLs e e-mails são preservados intactos.
//
// Retorna { text, suspicious }: `suspicious=true` sinaliza que SOBROU algo provável
// de corrupção que o determinístico não resolveu — o chamador pode então acionar a
// passada de revisão por IA (gated). Em texto normal, `suspicious` fica false e
// nenhuma IA extra é chamada.

import { PT_WORDS } from "./pt-dictionary.ts";

// Palavras de 1 letra VÁLIDAS em PT (o léxico só tem tokens >=2; estas entram aqui).
// Lista fechada de propósito: NÃO incluir "i/s/t/x..." (ruído do corpus) senão
// dividiríamos palavras legítimas letra a letra.
const ONE_CHAR_WORDS = new Set(["a", "e", "o", "é", "à"]);

// PALAVRAS-FUNÇÃO (classe fechada, 1–2 letras). Só ESTAS podem ser o pedaço "curto"
// de uma divisão. Sem isto, "login" (ausente do léxico) viraria "lo"+"gin" (ambos no
// corpus). Como "lo"/"gin" não são palavras-função, a divisão é barrada e "login"
// fica intacto; já "o tema"/"de curso"/"é a" passam (o/de/é são palavras-função).
const FUNCTION_WORDS = new Set([
    "a", "e", "o", "é", "à",
    "de", "do", "da", "em", "no", "na", "um", "ao", "ou", "se", "os", "as", "me", "te", "às",
]);

// Estrangeirismos/termos de domínio comuns no suporte Moodle que NÃO estão no corpus
// de frequência PT — registramos aqui para (a) nunca serem divididos e (b) servirem
// de pedaço válido numa divisão. Defesa extra além da regra de palavras-função.
const EXTRA_WORDS = new Set([
    "login", "logins", "logout", "email", "emails", "online", "offline", "site", "sites",
    "link", "links", "web", "internet", "upload", "download", "app", "apps", "status",
    "moodle", "feedback", "quiz", "quizzes", "url", "urls", "pdf", "pdfs", "wifi", "tablet",
    "smartphone", "notebook", "desktop", "browser", "cookies", "backup", "chat", "chats",
]);

// Um pedaço é "léxico" se: 1 letra -> está na allowlist; >=2 letras -> está no PT_WORDS
// (corpus de frequência) ou no EXTRA_WORDS (estrangeirismos de domínio).
function inLexicon(seg: string): boolean {
    if (seg.length === 1) return ONE_CHAR_WORDS.has(seg);
    return PT_WORDS.has(seg) || EXTRA_WORDS.has(seg);
}

const MAX_SEGMENTS = 3;          // glue real raramente é >3 palavras; acima disso, suspeito de retalhar palavra real
const MAX_SPLIT_LEN = 40;        // não tenta segmentar tokens gigantes (limita custo da DP)
const SUSPICIOUS_LEN = 16;       // token alfabético desconhecido >= isto e não-segmentável -> sinaliza revisão IA

// Word-break (programação dinâmica): menor nº de segmentos do léxico que cobre `s`
// inteiro, ou null. Prefere palavras LONGAS (tenta j do fim pro início) -> menos
// segmentos e particionamento mais natural ("conteúdoacadêmico" -> conteúdo+acadêmico,
// não con+teú+do+...). `s` deve estar em minúsculas.
function segment(s: string): string[] | null {
    const n = s.length;
    const memo = new Map<number, string[] | null>();
    function go(i: number): string[] | null {
        if (i === n) return [];
        const cached = memo.get(i);
        if (cached !== undefined) return cached;
        let best: string[] | null = null;
        for (let j = n; j > i; j--) {
            const part = s.slice(i, j);
            if (!inLexicon(part)) continue;
            const rest = go(j);
            if (rest === null) continue;
            const cand = [part, ...rest];
            if (best === null || cand.length < best.length) best = cand;
        }
        memo.set(i, best);
        return best;
    }
    return go(0);
}

// Decide a partição de UM token (run de letras). Devolve o token reescrito com
// espaços, ou null se não há divisão segura (chamador mantém o original).
// `original` preserva caixa/acentos; segmentamos a versão minúscula e recortamos
// o original pelos mesmos offsets (toLowerCase preserva o comprimento em PT/latim).
function splitGluedToken(original: string): string | null {
    if (original.length < 2 || original.length > MAX_SPLIT_LEN) return null;
    // Acrônimos em CAIXA ALTA (CPF, CEAD; "UnB" não é all-caps) ficam intactos.
    if (original.length > 1 && original === original.toUpperCase()) return null;
    const lower = original.toLowerCase();
    if (inLexicon(lower)) return null;                 // já é palavra válida -> não toca

    const segs = segment(lower);
    if (!segs || segs.length < 2 || segs.length > MAX_SEGMENTS) return null;

    // Guarda anti-retalho (evita estragar palavra legítima/estrangeira ausente do
    // léxico, ex.: "login" -> "lo gin"):
    //  - TODO pedaço curto (<=2 letras) precisa ser PALAVRA-FUNÇÃO; e
    //  - precisa haver ao menos um pedaço "longo" (>=3 letras),
    //    EXCETO o caso legítimo de duas palavras de 1 letra grudadas ("é a" -> "éa").
    const allOneChar = segs.length === 2 && segs.every((p) => p.length === 1);
    const shortsAllFunction = segs.filter((p) => p.length <= 2).every((p) => FUNCTION_WORDS.has(p));
    const hasLong = segs.some((p) => p.length >= 3);
    if (!shortsAllFunction) return null;
    if (!hasLong && !allOneChar) return null;

    // Recorta o ORIGINAL pelos comprimentos dos segmentos (preserva caixa/acentos).
    const parts: string[] = [];
    let off = 0;
    for (const seg of segs) {
        parts.push(original.slice(off, off + seg.length));
        off += seg.length;
    }
    return parts.join(" ");
}

// ── Proteção de regiões que NÃO podem ser tocadas (código, URLs, e-mails) ───────
// Sentinela = par de chars da Área de Uso Privado do Unicode (U+E000 / U+E001,
// categoria Co — NÃO são letras nem pontuação) com o índice em dígitos no meio.
// Assim o placeholder sobrevive intacto às regex de pontuação e de de-aglutinação
// (\p{L}+ não casa PUA nem dígitos) e é restaurável sem ambiguidade.
interface Protected { text: string; tokens: string[]; }
const PH_OPEN = "";
const PH_CLOSE = "";

function protect(text: string): Protected {
    const tokens: string[] = [];
    const stash = (m: string): string => {
        tokens.push(m);
        return `${PH_OPEN}${tokens.length - 1}${PH_CLOSE}`;
    };
    let t = text;
    t = t.replace(/```[\s\S]*?```/g, stash);                  // blocos de código cercados
    t = t.replace(/`[^`\n]*`/g, stash);                       // inline code
    t = t.replace(/!?\[[^\]]*\]\([^)]*\)/g, stash);           // links/imagens markdown (alvo + url)
    t = t.replace(/\b(?:https?:\/\/|www\.)[^\s)]+/gi, stash);  // URLs cruas
    t = t.replace(/\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g, stash);     // e-mails
    return { text: t, tokens };
}
function restore(text: string, tokens: string[]): string {
    return text.replace(/(\d+)/g, (_m, i) => tokens[Number(i)] ?? "");
}

// ── Correções de ESPAÇAMENTO em torno de pontuação (fora de código) ────────────
function fixPunctuationSpacing(text: string): string {
    let t = text;
    // Vírgula/;/:/!/? grudados na PRÓXIMA palavra (letra). Lookahead exige LETRA,
    // então "1,5" e "12:30" (dígito após) ficam intactos.
    t = t.replace(/([,;:!?])(?=[A-Za-zÀ-ÿ])/g, "$1 ");
    // Ponto final grudado: só quando minúscula + "." + MAIÚSCULA ("passo.Dúvidas").
    // Evita decimais ("3.14": dígito) e siglas ("U.S": maiúscula antes).
    t = t.replace(/([a-zà-ÿ])\.([A-ZÀ-Þ])/g, "$1. $2");
    // Reticências grudadas em letra.
    t = t.replace(/(\.{3}|…)(?=[A-Za-zÀ-ÿ])/g, "$1 ");
    // Espaços horizontais duplicados criados pelos passos acima (não mexe em \n).
    t = t.replace(/[^\S\n]{2,}/g, " ");
    return t;
}

// ── Detecção de resíduo suspeito (gate p/ revisão por IA) ──────────────────────
// Conservador: só sinaliza sinais FORTES de corrupção que sobraram, pra IA quase
// nunca disparar em texto já bom.
function hasSuspiciousResidue(text: string): boolean {
    const runs = text.match(/\p{L}+/gu) || [];
    for (const run of runs) {
        // camelGlue residual: minúscula seguida de MAIÚSCULA dentro de palavra ("diretaE").
        if (run.length >= 4 && /\p{Ll}\p{Lu}/u.test(run)) return true;
        // token longo, desconhecido, não-acrônimo e não-segmentável -> provável grude/garbage.
        if (run.length >= SUSPICIOUS_LEN) {
            const lower = run.toLowerCase();
            const isAcronym = run === run.toUpperCase();
            if (!isAcronym && !inLexicon(lower) && !segment(lower)) return true;
        }
    }
    return false;
}

export interface RepairResult { text: string; suspicious: boolean; }

// API principal: repara `text` (idempotente, seguro em texto já correto) e diz se
// ainda parece haver corrupção residual (gate da revisão por IA).
export function repairPortugueseText(input: string | null | undefined): RepairResult {
    if (!input) return { text: "", suspicious: false };

    const { text: masked, tokens } = protect(input);

    // 1) Espaçamento de pontuação.
    let t = fixPunctuationSpacing(masked);

    // 2) De-aglutinação por palavra (runs de letras; pontuação/markdown não entram).
    t = t.replace(/\p{L}+/gu, (run) => splitGluedToken(run) ?? run);

    const suspicious = hasSuspiciousResidue(t);
    const restored = restore(t, tokens);
    return { text: restored, suspicious };
}

