// produzia, e executeTool() aplica os MESMOS guards (STUDENT_BLOCKED_TOOLS, enforce
// de courseId, SSRF) com o MESMO comportamento.
//
// Estrutura do registry: cada tool = { name, description, parameters, gating, execute }.
//   - description/parameters: estaticos OU funcao(ctx) quando dependem do contexto
//     (ex.: update_student_mastery embute a lista de modulos do curso).
//   - gating: predicado (ctx) => boolean que decide se a tool aparece para o role/curso.
//   - execute(args, ctx): o corpo do executor (mesma logica de antes).
// Os dois adapters (toOpenAITools agora; toRealtimeTools na US-010) derivam do MESMO
// registry — por isso cada adapter fica trivial.

import { fetchAndExtractFileContent, resolveUserRole } from "./moodle.ts";

// ── Tools restritas a professores (alunos nao podem chamar) ──────────────────
export const STUDENT_BLOCKED_TOOLS = new Set([
    "core_enrol_get_enrolled_users",
    "core_user_get_course_user_profiles",
    "core_notes_create_notes",
    "core_message_send_instant_messages",
]);

// ── Contexto de montagem do registry (entrada dos adapters) ──────────────────
// Reproduz os parametros que buildInternalToolDefinitions recebia.
export interface ToolBuildContext {
    hasSupabase: boolean;
    context: any;
    courseModules: string[];
}

// ── Contexto de execucao (entrada do executor) ───────────────────────────────
// Reproduz os parametros que o antigo executeTool recebia (moodleBase, moodleToken,
// supabase, context) num unico objeto, mantendo a MESMA semantica.
export interface ToolExecContext {
    moodleBase: string;
    moodleToken: string;
    supabase: any | null;
    context: any;
}

export interface ToolRegistryEntry {
    name: string;
    // description/parameters: estaticos ou derivados do contexto de montagem.
    description: string | ((ctx: ToolBuildContext) => string);
    parameters: any | ((ctx: ToolBuildContext) => any);
    // gating: a tool aparece (e e elegivel) so quando isto retorna true.
    gating: (ctx: ToolBuildContext) => boolean;
    // execute: corpo do executor — mesma logica de antes.
    execute: (args: Record<string, any>, ctx: ToolExecContext) => any | Promise<any>;
}

// ── REGISTRY canonico ─────────────────────────────────────────────────────────
// A ORDEM aqui reproduz a ordem de push() do buildInternalToolDefinitions original,
// para que toOpenAITools() devolva o array na MESMA ordem de antes.
export const TOOL_REGISTRY: ToolRegistryEntry[] = [
    // ── update_student_mastery — apenas alunos com Supabase ──────────────────
    {
        name: "update_student_mastery",
        gating: (ctx) => ctx.hasSupabase && resolveUserRole(ctx.context) !== "teacher",
        description: (ctx) => {
            const modulesList = ctx.courseModules.length > 0
                ? `\nTopicos validos deste curso (use EXATAMENTE um destes nomes): ${ctx.courseModules.slice(0, 25).join(' | ')}`
                : '';
            return `Atualiza o nivel de dominio do aluno em um topico do curso APENAS apos ele responder uma questao, resolver exercicio ou voce avaliar concretamente o desempenho dele. NAO chame para perguntas informativas, saudacoes ou conversas gerais. SOMENTE quando o aluno DEMONSTROU aprendizado ou erro em algo especifico.${modulesList}`;
