                    topicId = newTopic?.id;
                }

                const { data: currentMastery } = await supabase
                    .from('learning_student_mastery').select('mastery_level')
                    .eq('user_id', context.userId).eq('topic_id', topicId).maybeSingle();

                const newLevel = Math.min(1.0, Math.max(0.0,
                    (currentMastery?.mastery_level || 0.0) + (args.mastery_delta || 0)
                ));

                await supabase.from('learning_student_mastery').upsert({
                    user_id: context.userId,
                    topic_id: topicId,
                    mastery_level: newLevel,
                    last_interaction_at: new Date().toISOString()
                }, { onConflict: 'user_id,topic_id' });

                // Higiene de log (LGPD): nao logar o nome do topico (conteudo do aluno),
                // so o nivel de mastery (numero, sem PII).
                console.log(`[TOOLS] Mastery atualizado → ${Math.round(newLevel * 100)}%`);
                return {
