                    new_mastery: newLevel,
                    message: `Progresso registrado: "${args.topic_name}" agora em ${Math.round(newLevel * 100)}%`
                };
            } catch (err: any) {
                return { error: "Erro ao salvar progresso: " + (err.message || String(err)) };
            }
        },
    },

