// US-010: a voz expõe o REGISTRY COMPLETO de tools (../_shared/tools.ts) via o
// adapter realtime toRealtimeTools (formato flat) e executa pelo executeTool
// compartilhado (mesmos guards do texto: STUDENT_BLOCKED_TOOLS, enforce de
// courseId, SSRF). REGISTRY_TOOL_NAMES roteia o dispatch entre o executor
// compartilhado e o pequeno complemento voice-only.
import { toRealtimeTools, executeTool, REGISTRY_TOOL_NAMES } from "../_shared/tools.ts";
// US-011 (Fase 4): paridade de hardening voz<->texto via núcleo compartilhado.
//  - KILL-SWITCH: COURSE_DARCY_ENABLED de ../_shared/config.ts — mesma flag do texto;
//    quando false, a voz vira suporte-only (anula courseId/type ANTES de montar
