const checkVoiceRateLimit = createRateLimiter(VOICE_SESSION_LIMIT, VOICE_SESSION_WINDOW_MS);

// Estado de telemetria por sessão (mutado em background pelo setup abaixo).
interface VoiceTelemetryState {
    userId: string | null;
    moodleUserId: number | null;
    userFullName: string | null;
    contentConsent: boolean;
}

// Resolve, em background, o UUID do usuário (tabela users) + consentimento de
// treino (has_training_consent, opt-out) + nome p/ redação de PII — mesmo padrão
// do texto. Best-effort: qualquer falha mantém os defaults (consent=true, id=null).
// deno-lint-ignore no-explicit-any
function runVoiceTelemetrySetup(supabase: any, tel: VoiceTelemetryState): void {
    const p = (async () => {
        try {
            const mid = tel.moodleUserId;
            if (!mid || mid <= 1) return;
            const { data: u } = await supabase
                .from("users")
                .select("id, moodle_full_name")
                .eq("moodle_user_id", mid)
                .single();
            if (u?.id) tel.userId = u.id;
            if (u?.moodle_full_name) tel.userFullName = u.moodle_full_name;
            if (tel.userId) {
                const { data: c } = await supabase.rpc("has_training_consent", { p_user_id: tel.userId });
                if (c === false) tel.contentConsent = false;
            }
        } catch (e) {
            console.warn("[darcy-voice] resolve consentimento/usuário falhou:", e instanceof Error ? e.message : String(e));
        }
    })();
    // Roda em background (não atrasa a abertura da sessão de voz).
    try {
