// ── core_notes_create_notes — apenas professores ─────────────────────────
{
    name: "core_notes_create_notes",
    gating: (ctx) => resolveUserRole(ctx.context) === "teacher",
    description: "Cria anotacoes pedagogicas no perfil de um aluno no Moodle. Use apenas quando o professor solicitar registrar uma observacao sobre um aluno. CONFIRME o texto e o aluno com o professor antes de executar.",
    parameters: {
        type: "object",
        properties: {
            notes: {
                type: "array",
                description: "Lista de anotacoes a criar",
                items: {
                    type: "object",
                    properties: {
                        userid: { type: "number", description: "ID Moodle do aluno" },
                        publishstate: {
                            type: "string",
                            enum: ["personal", "course", "public"],
                            description: "'personal'=so o professor, 'course'=professores do curso, 'public'=todos"
                        },
                        courseid: { type: "number", description: "ID do curso (usar o curso atual)" },
                        text: { type: "string", description: "Texto da anotacao pedagogica" },
                        format: { type: "number", description: "Formato: 2=plain (padrao)", default: 2 }
                    },
                    required: ["userid", "publishstate", "courseid", "text"]
                }
            }
        },
        required: ["notes"]
    },
    execute: async (args, { moodleBase, moodleToken }) => {
        try {
            const url = new URL(`${moodleBase}/webservice/rest/server.php`);
            url.searchParams.set('wstoken', moodleToken);
            url.searchParams.set('moodlewsrestformat', 'json');
            url.searchParams.set('wsfunction', 'core_notes_create_notes');
            const notes: any[] = args.notes || [];
            notes.forEach((note: any, i: number) => {
                url.searchParams.set(`notes[${i}][userid]`, String(note.userid));
                url.searchParams.set(`notes[${i}][publishstate]`, note.publishstate);
                url.searchParams.set(`notes[${i}][courseid]`, String(note.courseid));
                url.searchParams.set(`notes[${i}][text]`, note.text);
                url.searchParams.set(`notes[${i}][format]`, String(note.format ?? 2));
            });
            const res = await fetch(url.toString());
            if (!res.ok) return { error: `HTTP ${res.status}` };
            return { success: true, result: await res.json() };
        } catch (err) {
            return { error: "Erro ao criar nota: " + String(err) };
        }
    },
},

// ── generate_practice_quiz — apenas alunos ───────────────────────────────
{
    name: "generate_practice_quiz",
    gating: (ctx) => resolveUserRole(ctx.context) !== "teacher",
    description: 'Gera questões de prática para o aluno estudar. Use quando o aluno pedir para praticar, revisar, ou se preparar para avaliação. Gere questões progressivas (fácil→difícil) baseadas no conteúdo do curso.',
    parameters: {
        type: 'object',
        properties: {
            topic: { type: 'string', description: 'Tópico ou módulo do curso para gerar questões' },
            difficulty: { type: 'string', enum: ['facil', 'medio', 'dificil', 'progressivo'], description: 'Nível de dificuldade' },
            question_count: { type: 'integer', description: 'Número de questões (1-10)', minimum: 1, maximum: 10 },
        },
        required: ['topic', 'question_count'],
    },
    execute: (args) => {
        const topic = args.topic || 'geral';
        const count = Math.min(Math.max(args.question_count || 5, 1), 10);
        const difficulty = args.difficulty || 'progressivo';
        return `[QUIZ_MODE] Gere ${count} questões de prática sobre "${topic}" com dificuldade "${difficulty}". Use o conteúdo do curso no contexto. Para cada questão: apresente a pergunta, aguarde a resposta do aluno, avalie, e dê feedback Socrático. Após todas as questões, apresente um resumo com acertos/erros e recomendações de estudo.`;
    },
},

// ── update_student_profile — apenas alunos com Supabase ──────────────────
{
    name: "update_student_profile",
    gating: (ctx) => resolveUserRole(ctx.context) !== "teacher" && ctx.hasSupabase,
    description: 'Atualiza o perfil de aprendizagem do aluno. Use para registrar: estilo preferido de explicação, interesses pessoais (para analogias), áreas de dificuldade, e áreas fortes. Chame ao observar padrões no comportamento do aluno.',
    parameters: {
        type: 'object',
        properties: {
            preferred_style: { type: 'string', enum: ['analogias', 'exemplos_praticos', 'teoria_formal', 'visual', 'passo_a_passo'], description: 'Estilo preferido de explicação do aluno' },
            interests: { type: 'array', items: { type: 'string' }, description: 'Interesses pessoais do aluno (esportes, música, etc.) para usar em analogias' },
            struggle_areas: { type: 'array', items: { type: 'string' }, description: 'Áreas/tópicos onde o aluno demonstra dificuldade' },
            strong_areas: { type: 'array', items: { type: 'string' }, description: 'Áreas/tópicos onde o aluno demonstra domínio' },
            notes: { type: 'string', description: 'Observações gerais sobre o estilo de aprendizagem' },
        },
        required: [],
    },
    execute: async (args, { supabase, context }) => {
        if (!supabase || !context.userId) return { error: 'Perfil não disponível sem identificação do aluno.' };
        const moodleId = Number(context.userId);
        if (!moodleId || moodleId <= 0) return { error: 'ID do aluno inválido.' };

        const updateData: any = { updated_at: new Date().toISOString() };
        if (args.preferred_style) updateData.preferred_explanation_style = args.preferred_style;
        if (args.interests?.length) updateData.interests = args.interests;
        if (args.struggle_areas?.length) updateData.struggle_areas = args.struggle_areas;
        if (args.strong_areas?.length) updateData.strong_areas = args.strong_areas;
        if (args.notes) updateData.personality_notes = args.notes;

        const { error } = await supabase
            .from('student_profiles')
            .upsert({ moodle_user_id: moodleId, ...updateData }, { onConflict: 'moodle_user_id' });

        // Higiene de log (LGPD): logar so code/message do erro — o objeto de erro
        // do supabase pode ecoar os valores do perfil (interests, notes, etc.).
        if (error) { console.error('[TOOLS] Profile update error:', error?.code || '', error?.message || ''); return 'Erro ao atualizar perfil.'; }
        return `Perfil do aluno atualizado: ${JSON.stringify(args)}`;
    },
},

// ── get_course_analytics — apenas professores ────────────────────────────
{
    name: "get_course_analytics",
    gating: (ctx) => resolveUserRole(ctx.context) === "teacher",
    description: 'Retorna análise detalhada do curso. Use quando o professor perguntar sobre desempenho da turma, alunos em risco, entregas pendentes, ou métricas do curso.',
    parameters: {
        type: 'object',
        properties: {
            analysis_type: {
                type: 'string',
                enum: ['overview', 'at_risk', 'assignments', 'grades', 'engagement'],
                description: 'Tipo de análise: overview (resumo geral), at_risk (alunos em risco), assignments (status de entregas), grades (distribuição de notas), engagement (engajamento)'
            },
        },
        required: ['analysis_type'],
    },
    execute: async (args, { moodleBase, moodleToken, context }) => {
        if (!moodleBase || !moodleToken || !context.courseId) return { error: 'Contexto do curso não disponível.' };
        const analysisType = args.analysis_type || 'overview';
        const courseId = context.courseId;

        // Fetch enrolled users
        const enrolledUrl = `${moodleBase}/webservice/rest/server.php?wstoken=${moodleToken}&wsfunction=core_enrol_get_enrolled_users&moodlewsrestformat=json&courseid=${courseId}`;
        const enrolledRes = await fetch(enrolledUrl);
        const enrolled = await enrolledRes.json();

        if (!Array.isArray(enrolled)) return { error: 'Erro ao buscar dados dos alunos.' };

        const students = enrolled.filter((u: any) =>
            u.roles?.some((r: any) => [5, 9].includes(r.roleid))
        );

        switch (analysisType) {
            case 'overview':
                return `Resumo do Curso:\n- Total de alunos: ${students.length}\n- Alunos com último acesso há mais de 7 dias: ${students.filter((s: any) => !s.lastcourseaccess || (Date.now()/1000 - s.lastcourseaccess > 7*86400)).length}\n- Alunos que nunca acessaram: ${students.filter((s: any) => !s.lastcourseaccess).length}`;

            case 'at_risk': {
                const atRisk = students.filter((s: any) =>
                    !s.lastcourseaccess || (Date.now()/1000 - s.lastcourseaccess > 7*86400)
                );
                const riskList = atRisk.slice(0, 20).map((s: any) => {
                    const days = s.lastcourseaccess ? Math.floor((Date.now()/1000 - s.lastcourseaccess) / 86400) : 'nunca';
                    return `- ${s.fullname} (último acesso: ${days === 'nunca' ? 'nunca' : days + ' dias atrás'})`;
                }).join('\n');
                return `Alunos em risco de evasão (${atRisk.length} total):\n${riskList}${atRisk.length > 20 ? `\n... e mais ${atRisk.length - 20} alunos` : ''}`;
            }

            case 'engagement': {
                const active7d = students.filter((s: any) => s.lastcourseaccess && (Date.now()/1000 - s.lastcourseaccess < 7*86400)).length;
                const active30d = students.filter((s: any) => s.lastcourseaccess && (Date.now()/1000 - s.lastcourseaccess < 30*86400)).length;
                return `Engajamento:\n- Ativos últimos 7 dias: ${active7d}/${students.length} (${Math.round(active7d/students.length*100)}%)\n- Ativos últimos 30 dias: ${active30d}/${students.length} (${Math.round(active30d/students.length*100)}%)\n- Inativos: ${students.length - active30d}/${students.length}`;
            }

            default:
                return `Tipo de análise "${analysisType}" não reconhecido. Use: overview, at_risk, assignments, grades, engagement.`;
        }
    },
},

